        self.set_parameter('ifhoSsbSmtcOffset', '0')
        self.set_parameter('nrSysInfoProfileDN', f'MRBTS-{bts_id}/NRBTS-{bts_id}/NRSYSINFO_PROFILE-1')
        self.set_parameter('rlfPsccTrigThresholdRsrp', '42')
        self.set_parameter('trackingAreaDN', f'MRBTS-{bts_id}/NRBTS-{bts_id}/TRACKINGAREA-1')
